// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { measuredFit, TOOLBAR_NARROW_AT, widestToTry } from "../../../main/frontend/graph-explorer/toolbar-fit.ts";

// The graph toolbar shows labels while everything fits on one row with them, then icons while those fit, and only then
// its narrow layout (the views on a row of their own, the actions spread below): it never wraps on its own.
const LABELS = 0;
const ICONS = 1;
const NARROW = 2;
const fresh = { level: LABELS, widths: [] };

test("labels stay while the labelled toolbar fits its width", () => {
  assert.deepEqual(measuredFit(fresh, 1300, 1150), { level: LABELS, widths: [1150] });
  assert.deepEqual(measuredFit(fresh, 1150, 1150), { level: LABELS, widths: [1150] });
});

test("a toolbar wider than its row takes the next step and remembers how wide it was", () => {
  assert.deepEqual(measuredFit(fresh, 1100, 1150), { level: ICONS, widths: [1150] });
  assert.deepEqual(measuredFit({ level: ICONS, widths: [1150] }, 1100, 808), { level: ICONS, widths: [1150, 808] });
  assert.deepEqual(measuredFit({ level: ICONS, widths: [1150] }, 726, 764), { level: NARROW, widths: [1150, 764] });
  assert.deepEqual(measuredFit({ level: NARROW, widths: [1150, 764] }, 700, 2000), { level: NARROW, widths: [1150, 764] },
    "the narrow layout says nothing about one row");
});

test("a toolbar goes back to the widest step that fitted this width when last measured", () => {
  const narrow = { level: NARROW, widths: [1150, 764] };
  assert.equal(widestToTry(narrow, 700), NARROW);
  assert.equal(widestToTry(narrow, 764), ICONS);
  assert.equal(widestToTry(narrow, 1149), ICONS);
  assert.equal(widestToTry(narrow, 1150), LABELS);
  assert.equal(widestToTry({ level: ICONS, widths: [] }, 900), LABELS, "never measured with labels: try them");
  assert.equal(widestToTry({ level: NARROW, widths: [1150] }, 900), ICONS, "never measured with icons: try them");
});

test("a toolbar in a narrow panel always takes the narrow layout and learns nothing from it", () => {
  assert.equal(TOOLBAR_NARROW_AT, 640);
  assert.deepEqual(measuredFit(fresh, 640, 1400), { level: NARROW, widths: [] });
  assert.equal(widestToTry({ level: NARROW, widths: [] }, 640), NARROW);
  assert.equal(widestToTry({ level: NARROW, widths: [] }, 641), LABELS, "once wider, labels are tried again");
});
